"use client";

import { useId } from "react";
import { ChartBar } from "@phosphor-icons/react/dist/ssr/ChartBar";
import { User } from "@phosphor-icons/react/dist/ssr/User";
import { DeviceMobile } from "@phosphor-icons/react/dist/ssr/DeviceMobile";
import { Truck } from "@phosphor-icons/react/dist/ssr/Truck";
import { Shield } from "@phosphor-icons/react/dist/ssr/Shield";
import { GoogleChromeLogo } from "@phosphor-icons/react/dist/ssr/GoogleChromeLogo";
import { Check } from "@phosphor-icons/react/dist/ssr/Check";
import styles from "./ProductInterestCards.module.css";

export interface ProductOption {
  id: string;
  name: string;
  subtitle: string;
  icon: typeof ChartBar;
  customTitleRender?: () => React.ReactNode;
}

export const PRODUCT_OPTIONS: ProductOption[] = [
  {
    id: "lens",
    name: "Spotter Lens",
    subtitle: "Market data analytics and freight rankings",
    icon: ChartBar,
  },
  {
    id: "crm",
    name: "Spotter CRM",
    subtitle: "Recruiting engine with engagement visibility",
    icon: User,
    customTitleRender: () => (
      <span className={styles.productTitleFlex}>
        <span className={styles.crmBadge}>Spotter</span>
        <span className={styles.productTitleText}>CRM</span>
      </span>
    ),
  },
  {
    id: "driver-app",
    name: "Driver App",
    subtitle: "Load score optimization and matching",
    icon: DeviceMobile,
  },
  {
    id: "tms",
    name: "Spotter TMS + fuelseek",
    subtitle: "Visibility engine with data automation",
    icon: Truck,
    customTitleRender: () => (
      <span className={styles.productTitleFlex}>
        <span className={styles.productTitleText}>Spotter TMS + </span>
        <span className={styles.fuelseekAccent}>fuelseek</span>
      </span>
    ),
  },
  {
    id: "sentinel",
    name: "Spotter Sentinel",
    subtitle: "Driver score and safety automation",
    icon: Shield,
  },
  {
    id: "extension",
    name: "Load Board Extension",
    subtitle: "Browser automation for Chrome & Firefox",
    icon: GoogleChromeLogo,
  },
];

interface ProductInterestCardsProps {
  selectedProducts: string[];
  onChange: (newSelection: string[]) => void;
}

/**
 * 6-card multi-select product grid.
 * Replicates the exact visual design from the Spotter quote form reference:
 * - 2 columns x 3 rows grid
 * - Product icons + titles + subtitles
 * - Interactive custom checkboxes
 * - Full keyboard navigation (Space / Enter toggle)
 */
export function ProductInterestCards({
  selectedProducts,
  onChange,
}: ProductInterestCardsProps) {
  const baseId = useId();

  const toggleProduct = (productId: string) => {
    if (selectedProducts.includes(productId)) {
      onChange(selectedProducts.filter((id) => id !== productId));
    } else {
      onChange([...selectedProducts, productId]);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent, productId: string) => {
    if (e.key === " " || e.key === "Enter") {
      e.preventDefault();
      toggleProduct(productId);
    }
  };

  return (
    <div
      className={styles.productGrid}
      role="group"
      aria-labelledby="product-interest-label"
    >
      {PRODUCT_OPTIONS.map((prod) => {
        const isChecked = selectedProducts.includes(prod.id);
        const IconComponent = prod.icon;
        const cardId = `${baseId}-${prod.id}`;

        return (
          <div
            key={prod.id}
            id={cardId}
            role="checkbox"
            aria-checked={isChecked}
            tabIndex={0}
            onClick={() => toggleProduct(prod.id)}
            onKeyDown={(e) => handleKeyDown(e, prod.id)}
            className={`${styles.card} ${isChecked ? styles.cardSelected : ""}`}
            data-testid={`product-card-${prod.id}`}
          >
            <div className={styles.iconContainer} aria-hidden="true">
              <IconComponent size={20} weight="regular" />
            </div>

            <div className={styles.cardContent}>
              <div className={styles.cardTitle}>
                {prod.customTitleRender ? (
                  prod.customTitleRender()
                ) : (
                  <span className={styles.productTitleText}>{prod.name}</span>
                )}
              </div>
              <div className={styles.cardSubtitle}>{prod.subtitle}</div>
            </div>

            <div
              className={`${styles.checkbox} ${
                isChecked ? styles.checkboxChecked : ""
              }`}
              aria-hidden="true"
            >
              {isChecked && <Check size={12} weight="bold" color="#ffffff" />}
            </div>
          </div>
        );
      })}
    </div>
  );
}
